// Firestore REST (v1) value encoding. n8n talks to Firestore through HTTP Request nodes with a
// Google service account, so documents travel as typed "fields" maps.

const TIMESTAMP_KEYS = new Set(["firstSeenAt", "lastSeenAt", "createdAt", "computedAt", "updatedAt"]);

function toValue(v, key) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === "boolean") return { booleanValue: v };
  if (typeof v === "number") return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (typeof v === "string") return TIMESTAMP_KEYS.has(key) ? { timestampValue: v } : { stringValue: v };
  if (Array.isArray(v)) return { arrayValue: v.length ? { values: v.map((x) => toValue(x)) } : {} };
  if (typeof v === "object") return { mapValue: { fields: toFields(v) } };
  throw new Error(`Cannot encode ${typeof v}`);
}

function toFields(obj) {
  const out = {};
  for (const [k, v] of Object.entries(obj)) if (v !== undefined) out[k] = toValue(v, k);
  return out;
}

function fromValue(v) {
  if (!v || "nullValue" in v) return null;
  if ("booleanValue" in v) return v.booleanValue;
  if ("integerValue" in v) return Number(v.integerValue);
  if ("doubleValue" in v) return v.doubleValue;
  if ("stringValue" in v) return v.stringValue;
  if ("timestampValue" in v) return v.timestampValue;
  if ("referenceValue" in v) return v.referenceValue;
  if ("arrayValue" in v) return (v.arrayValue.values ?? []).map(fromValue);
  if ("mapValue" in v) return fromFields(v.mapValue.fields ?? {});
  return null;
}

function fromFields(fields = {}) {
  return Object.fromEntries(Object.entries(fields).map(([k, v]) => [k, fromValue(v)]));
}

/** Last path segment of a Firestore document name. */
const docId = (name) => name.split("/").pop();

/** documents:runQuery body for `collection where field == value`. */
function equalityQuery(collection, field, value, limit = 5) {
  return {
    structuredQuery: {
      from: [{ collectionId: collection }],
      where: { fieldFilter: { field: { fieldPath: field }, op: "EQUAL", value: toValue(value) } },
      limit,
    },
  };
}

/** documents:runQuery body for `collection where field is set and not null`. */
function notNullQuery(collection, field, limit = 20) {
  return {
    structuredQuery: {
      from: [{ collectionId: collection }],
      where: { unaryFilter: { field: { fieldPath: field }, op: "IS_NOT_NULL" } },
      limit,
    },
  };
}

/** documents from a runQuery response (array of { document?, readTime }). */
function queryDocs(body) {
  return (Array.isArray(body) ? body : [])
    .filter((r) => r.document)
    .map((r) => ({ id: docId(r.document.name), ...fromFields(r.document.fields) }));
}

/** documents:commit write that sets only the given fields of an existing or new document. */
function updateWrite(name, data, { merge = true } = {}) {
  return {
    update: { name, fields: toFields(data) },
    ...(merge ? { updateMask: { fieldPaths: Object.keys(data) } } : {}),
  };
}

// ---- src/context.js ----
// Loads what every run needs once: config/criteria, the latest profile and its few-shot examples.

const RATERS = ["philipp", "manuela"];

/** documents:batchGet body for criteria + few-shot listings + both raters' ratings. */
function contextBatchGet(projectId, profile) {
  const base = `projects/${projectId}/databases/(default)/documents`;
  const ids = profile?.fewShot ?? [];
  return {
    documents: [
      `${base}/config/criteria`,
      ...ids.map((id) => `${base}/listings/${id}`),
      ...ids.flatMap((id) => RATERS.map((r) => `${base}/ratings/${id}_${r}`)),
    ],
  };
}

/**
 * batchGet response (array of { found } | { missing }) → { criteria, examples }.
 * An example's score is the mean of both ratings (spec §6.3 "Uneinigkeit").
 */
function readContext(batchBody, profile) {
  const found = (Array.isArray(batchBody) ? batchBody : [])
    .filter((r) => r.found)
    .map((r) => ({ path: r.found.name, id: docId(r.found.name), data: fromFields(r.found.fields) }));
  const criteria = found.find((d) => d.path.endsWith("/config/criteria"))?.data ?? {};
  const examples = (profile?.fewShot ?? [])
    .map((id) => {
      const listing = found.find((d) => d.path.endsWith(`/listings/${id}`))?.data;
      const ratings = RATERS.map((r) => found.find((d) => d.path.endsWith(`/ratings/${id}_${r}`))?.data)
        .filter((r) => r && r.score != null);
      if (!listing || !ratings.length) return null;
      const score = Math.round((ratings.reduce((a, r) => a + r.score, 0) / ratings.length) * 2) / 2;
      return {
        listing,
        score,
        tags: [...new Set(ratings.flatMap((r) => r.tags ?? []))],
        notes: ratings.map((r) => r.note).filter(Boolean),
      };
    })
    .filter(Boolean);
  return { criteria, examples };
}

// ---- node ----
const s = $('Settings').first().json;
const r = $input.first().json;
if (r.statusCode !== 200) throw new Error(`Firestore profiles: ${r.statusCode} ${JSON.stringify(r.body).slice(0, 300)}`);
const profile = queryDocs(r.body)[0] ?? null;
return [{ json: { profile, batchGet: contextBatchGet(s.projectId, profile) } }];

