  if (agent) out.agent = agent[1].trim();
  if (/\breduced\b/i.test(text)) out.priceReduced = true;
  const avail = /available\s+(?:from\s+)?(now|immediately|\d{1,2}(?:st|nd|rd|th)?\s+[A-Za-z]{3,9}\s+\d{4}|\d{1,2}\/\d{1,2}\/\d{2,4}|[A-Za-z]{3,9}\s+\d{4})/i.exec(text);
  if (avail) out.availableText = avail[1];
  return out;
}

/** True when the parser found enough to skip the Gemini fallback (spec §5.3 node 4). */
function isComplete(l) {
  return l.price != null && l.beds != null && (l.address != null || l.postcode != null) && l.url != null;
}

/** Full parse of one alert mail ({ id, from, subject, date, html, text }, see agentmail.js). */
function parseMail(mail) {
  const from = mail.from?.value?.[0]?.address ?? mail.from?.text ?? String(mail.from ?? "");
  const source = sourceForSender(from);
  const text = mail.html ? htmlToText(mail.html) : String(mail.text ?? "");
  // OnTheMarket sends price cuts as their own alert ("Reduced price properties in …").
  const reducedMail = /^reduced/i.test(String(mail.subject ?? "").trim());
  const listings = listingBlocks(text).map(readBlock).map((l) => (reducedMail ? { ...l, priceReduced: true } : l));
  const needsLlm = !portalForSender(from) || listings.length === 0 || listings.some((l) => !isComplete(l));
  return {
    messageId: mail.id ?? mail.messageId ?? null,
    from,
    subject: mail.subject ?? "",
    receivedAt: mail.date ?? null,
    source,
    text,
    listings,
    needsLlm,
  };
}

// ---- src/normalize.js ----
// Normalising (spec §5.3 node 5): price to pcm, let type and furnishing to the enums of §5.4,
// postcode sector, area, fingerprint for duplicates, and the flags that need only listing data.

/** Postcode district → area name, for when the mail names no place (spec §5.2 areas first). */
const AREAS = {
  TW10: "Richmond / Ham / Petersham",
  TW9: "Richmond / Kew",
  TW1: "Twickenham",
  TW2: "Twickenham",
  KT1: "Kingston",
  KT2: "North Kingston",
  KT3: "New Malden",
  SW13: "Barnes",
  SW14: "East Sheen / Mortlake",
  SW15: "Putney / Roehampton",
  SW18: "Southfields / Wandsworth",
  SW19: "Wimbledon",
  SW20: "Raynes Park",
};

const LET_TYPES = ["short_let", "flexible", "periodic", "corporate", "licence", "unknown"];
const FURNISHED = ["furnished", "part", "unfurnished", "either", "unknown"];
const PROPERTY_TYPES = ["flat", "maisonette", "detached", "semi_detached", "terraced", "house", "unknown"];

/** "semi-detached house", "apartment", "end of terrace house" → PROPERTY_TYPES. */
function propertyTypeFromText(t) {
  if (!t) return "unknown";
  const s = t.toLowerCase();
  if (/semi[\s-]?detached/.test(s)) return "semi_detached";
  if (/detached/.test(s)) return "detached";
  if (/terrace|mews/.test(s)) return "terraced";
  if (/maisonette|duplex/.test(s)) return "maisonette";
  if (/flat|apartment|penthouse|studio/.test(s)) return "flat";
  if (/house|bungalow|cottage|home/.test(s)) return "house";
  return "unknown";
}

function letTypeFromText(t) {
  if (!t) return "unknown";
  const s = t.toLowerCase();
  if (/licen[cs]e/.test(s)) return "licence";
  if (/corporate/.test(s)) return "corporate";
  if (/short/.test(s)) return "short_let";
  if (/flexible/.test(s)) return "flexible";
  if (/long/.test(s)) return "periodic";
  return "unknown";
}

function termFromText(t) {
  if (!t) return { min: null, max: null };
  const range = /(\d+)\s*(?:-|to)\s*(\d+)\s*months?/i.exec(t);
  if (range) return { min: Number(range[1]), max: Number(range[2]) };
  const min = /min(?:imum)?\.?\s*(?:term|tenancy)?\s*:?\s*(\d+)\s*months?/i.exec(t);
  const max = /max(?:imum)?\.?\s*(?:term|tenancy)?\s*:?\s*(\d+)\s*months?/i.exec(t);
  return { min: min ? Number(min[1]) : null, max: max ? Number(max[1]) : null };
}

function furnishedFromText(t) {
  if (!t) return "unknown";
  const s = t.toLowerCase();
  if (/furnished\s+or\s+unfurnished/.test(s)) return "either";
  if (/part/.test(s)) return "part";
  if (/unfurnished/.test(s)) return "unfurnished";
  if (/furnished/.test(s)) return "furnished";
  return "unknown";
}

const MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];

/** "now", "1st January 2028", "01/01/2028", "Jan 2028" → ISO date; "now" → today. */
function dateFromText(t, today = new Date()) {
  if (!t) return null;
  const s = t.trim().toLowerCase();
  if (/^(now|immediately)$/.test(s)) return today.toISOString().slice(0, 10);
  const iso = (y, m, d) => `${y}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  let m = /^(\d{1,2})(?:st|nd|rd|th)?\s+([a-z]{3,9})\s+(\d{4})$/.exec(s);
  if (m && MONTHS.indexOf(m[2].slice(0, 3)) >= 0) return iso(m[3], MONTHS.indexOf(m[2].slice(0, 3)) + 1, m[1]);
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/.exec(s);
  if (m) return iso(m[3].length === 2 ? `20${m[3]}` : m[3], m[2], m[1]);
  m = /^([a-z]{3,9})\s+(\d{4})$/.exec(s);
  if (m && MONTHS.indexOf(m[1].slice(0, 3)) >= 0) return iso(m[2], MONTHS.indexOf(m[1].slice(0, 3)) + 1, 1);
  return null;
}

/** Parser output (texts) → the extraction shape the Gemini fallback also returns. */
function fromParser(l, today) {
  const term = termFromText(l.letText);
  return {
    url: l.url,
    sourceId: l.sourceId,
    address: l.address,
    postcode: l.postcode,
    area: null,
    price: l.price,
    pricePeriod: l.pricePeriod,
    billsIncluded: l.billsIncluded,
    letType: letTypeFromText(l.letText),
    minTermMonths: term.min,
    maxTermMonths: term.max,
    availableFrom: dateFromText(l.availableText, today),
    beds: l.beds,
    baths: l.baths,
    furnished: furnishedFromText(l.furnishedText),
    garden: l.garden,
    parking: l.parking,
    epc: null,
    highlight: null,
    photos: l.photos ?? [],
    propertyType: propertyTypeFromText(l.typeText),
    agent: l.agent ?? null,
    priceReduced: l.priceReduced ?? null,
  };
}

/** "tw10 7ah" → { full: "TW10 7AH", district: "TW10", sector: "TW10 7" }. */
function splitPostcode(pc) {
  if (!pc) return { full: null, district: null, sector: null };
  // Portals send the full postcode, the sector ("TW11 8") or only the district ("TW11").
  const m = /^([A-Z]{1,2}\d[A-Z\d]?)\s*(?:(\d)([A-Z]{2})?)?$/.exec(pc.trim().toUpperCase());
  if (!m) return { full: null, district: null, sector: null };
  return {
    full: m[3] ? `${m[1]} ${m[2]}${m[3]}` : null,
    district: m[1],
    sector: m[2] ? `${m[1]} ${m[2]}` : m[1],
  };
}

function priceMonthly(price, period) {
  if (price == null) return null;
  // Alert mails without a period are monthly in practice; weekly prices say "pw".
  return period === "week" ? Math.round((price * 52) / 12) : Math.round(price);
}

// Street words that mark the street part of an address ("Kings Road, Kingston Upon Thames, KT2").
const STREET = /\b(road|rd|street|st|avenue|ave|lane|ln|close|crescent|cres|drive|dr|gardens|gdns|grove|place|pl|square|sq|terrace|way|walk|court|ct|mews|park|hill|row|parade|green|vale|rise|mount|common|gate|yard|wharf|chase|view|end|side)\b/;
const SHORT = [[/\b(road|rd)\b/g, "rd"], [/\b(street|st)\b/g, "st"], [/\b(avenue|ave)\b/g, "ave"], [/\b(lane|ln)\b/g, "ln"],
  [/\b(crescent|cres)\b/g, "cres"], [/\b(drive|dr)\b/g, "dr"], [/\b(gardens|gdns)\b/g, "gdns"], [/\b(place|pl)\b/g, "pl"],
  [/\b(square|sq)\b/g, "sq"], [/\b(court|ct)\b/g, "ct"]];

/**
 * Key for duplicate detection across portals: street + postcode district + bedrooms.
 * Portals name the place differently ("Gainsborough Road, Kew TW9" / "Gainsborough Road,
 * Richmond, TW9"), so only the street counts. Without a recognisable street there is no key
 * (empty string) and the listing is never treated as a duplicate.
 */
function fingerprint(address, district, beds) {
  const parts = (address ?? "")
    .toLowerCase()
    .split(/,|\s[-–]\s/)
    .map((p) => p
      .replace(/\b(flat|apartment|apt|unit|plot)\s*[\w-]+/g, " ")
      .replace(/\b[a-z]{1,2}\d[a-z\d]?(\s*\d([a-z]{2})?)?\b/g, " ")
      .replace(/\b\d+[a-z]?\b/g, " ")
      .replace(/[^a-z ]+/g, " ")
      .replace(/\s+/g, " ")
      .trim())
    .filter(Boolean);
  let street = parts.find((p) => STREET.test(p)) ?? "";
  for (const [re, short] of SHORT) street = street.replace(re, short);
  if (!street || !district) return "";
  return `${street}|${district.toLowerCase()}|${beds ?? ""}`;
}

/** Same house only if the rents are close; two flats in one street can share street, district and bedrooms. */
function samePrice(a, b, tolerance = 0.2) {
  if (a == null || b == null) return true;
  return Math.abs(a - b) <= tolerance * Math.max(a, b);
}

/** Firestore document ID: stable per portal listing so re-sent alerts update instead of duplicating. */
function listingId(source, sourceId, fp) {
  const base = sourceId ? `${source}-${sourceId}` : `${source}-${hash(fp)}`;
  return base.replace(/[^A-Za-z0-9_.-]/g, "-");
}

function hash(s) {
  let h = 2166136261;
  for (const ch of s) h = Math.imul(h ^ ch.charCodeAt(0), 16777619) >>> 0;
  return h.toString(36);
}

/** Flags from listing data and config/criteria. Commute flags are added once TfL has answered. */
function flags(l, criteria = {}) {
  const f = [];
  if (l.maxTermMonths != null && l.maxTermMonths < 6) f.push("term_too_short");
  if (criteria.maxPriceMonthly != null && l.priceMonthly != null && l.priceMonthly > criteria.maxPriceMonthly) f.push("over_budget");
  if (criteria.minBeds != null && l.beds != null && l.beds < criteria.minBeds) f.push("few_beds");
  if (l.letType === "periodic") f.push("periodic_risk");
  return f;
}

/** Extraction shape + mail context → listing fields of spec §5.4 (without commute/prediction). */
function normalize(x, ctx) {
  const pc = splitPostcode(x.postcode);
  const district = pc.district;
  const address = (x.address ?? "").trim() || (district ? `${district}` : "Adresse unbekannt");
  const area = x.area?.trim() || areaFromAddress(address) || AREAS[district] || "";
  const beds = x.beds ?? null;
  const fp = fingerprint(address, district, beds);
  const l = {
    source: ctx.source,
    sourceId: x.sourceId ?? null,
    url: x.url ?? null,
    fingerprint: fp,
    address,
    postcode: pc.sector ?? "",
    _postcodeFull: pc.full,
    area,
    priceMonthly: priceMonthly(x.price, x.pricePeriod),
    billsIncluded: x.billsIncluded ?? null,
    letType: LET_TYPES.includes(x.letType) ? x.letType : "unknown",
    minTermMonths: x.minTermMonths ?? null,
    maxTermMonths: x.maxTermMonths ?? null,
    availableFrom: x.availableFrom ?? null,
    beds,
    baths: x.baths ?? null,
    furnished: FURNISHED.includes(x.furnished) ? x.furnished : "unknown",
    propertyType: PROPERTY_TYPES.includes(x.propertyType) ? x.propertyType : "unknown",
    agent: x.agent?.trim() || null,
    priceReduced: x.priceReduced ?? null,
    garden: x.garden ?? null,
    parking: x.parking ?? null,
    epc: x.epc ?? null,
    highlight: x.highlight ?? null,
    photos: (x.photos ?? []).slice(0, 6),
    rawMessageId: ctx.messageId,
    extractedBy: ctx.extractedBy,
  };
  l.id = listingId(l.source, l.sourceId, fp);
  l.flags = flags(l, ctx.criteria);
  return l;
}

function areaFromAddress(address) {
  const parts = address.split(",").map((p) => p.trim()).filter(Boolean);
  if (parts.length < 2) return null;
  const last = parts[parts.length - 1].replace(/\b[A-Z]{1,2}\d[A-Z\d]?(\s*\d[A-Z]{2})?\b/g, "").trim();
  return last && !/^london$/i.test(last) ? last : parts.length > 2 ? parts[parts.length - 2] : null;
}

/** Next Monday as yyyymmdd – TfL plans the school run for a normal weekday at 08:15 arrival. */
function nextMonday(today = new Date()) {
  const d = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
  d.setUTCDate(d.getUTCDate() + (((8 - d.getUTCDay()) % 7) || 7));
  return d.toISOString().slice(0, 10).replace(/-/g, "");
}

// ---- src/gemini.js ----
// Gemini API requests (spec §5.3 nodes 4 and 8, §6.3). n8n sends them with an HTTP Request node
// to models/{model}:generateContent, so this builds plain request bodies and reads the answers.
// Every call uses structured output (responseMimeType + responseJsonSchema), so the answer text is
// valid JSON. The model is part of the URL, not the body (see build/lib.mjs).

const nullable = (type, extra = {}) => ({ type: [type, "null"], ...extra });

const EXTRACTION_SCHEMA = {
  type: "object",
  properties: {
    listings: {
      type: "array",
      items: {
        type: "object",
        properties: {
          url: nullable("string"),
          sourceId: nullable("string"),
          address: nullable("string"),
          postcode: nullable("string"),
          area: nullable("string"),
          price: nullable("number"),
          // "unknown" instead of null: enums with null are not reliably supported; readExtraction maps it back.
          pricePeriod: { type: "string", enum: ["month", "week", "unknown"] },
          billsIncluded: nullable("boolean"),
          letType: { type: "string", enum: ["short_let", "flexible", "periodic", "corporate", "licence", "unknown"] },
          minTermMonths: nullable("integer"),
          maxTermMonths: nullable("integer"),
          availableFrom: nullable("string"),
          beds: nullable("integer"),
          baths: nullable("integer"),
          furnished: { type: "string", enum: ["furnished", "part", "unfurnished", "either", "unknown"] },
          propertyType: { type: "string", enum: ["flat", "maisonette", "detached", "semi_detached", "terraced", "house", "unknown"] },
          agent: nullable("string"),
          priceReduced: nullable("boolean"),
          garden: nullable("boolean"),
          parking: nullable("boolean"),
          epc: nullable("string"),
          highlight: nullable("string"),
          photos: { type: "array", items: { type: "string" } },
        },
        required: [
          "url", "sourceId", "address", "postcode", "area", "price", "pricePeriod", "billsIncluded",
          "letType", "minTermMonths", "maxTermMonths", "availableFrom", "beds", "baths", "furnished",
          "propertyType", "agent", "priceReduced", "garden", "parking", "epc", "highlight", "photos",
        ],
        additionalProperties: false,
      },
    },
  },
  required: ["listings"],
  additionalProperties: false,
};

const PREDICTION_SCHEMA = {
  type: "object",
  properties: {
    score: { type: "integer", enum: [1, 2, 3, 4, 5] },
    rationale: { type: "string" },
  },
  required: ["score", "rationale"],
  additionalProperties: false,
};

// Mail text is passed in full; this only guards against a runaway newsletter.
const MAX_MAIL_CHARS = 120000;

const EXTRACTION_SYSTEM = `You extract rental listings from property alert emails (UK portals and letting agents).
The email text marks links as [[LINK:url]] and images as [[IMG:src]].
Return every distinct property the email advertises. Use null for anything the email does not state; never guess.
- url: the link that opens the listing (prefer the portal listing URL over tracking links if both appear).
- sourceId: the portal's numeric listing ID if visible in the URL, else null.
- price/pricePeriod: the rent as stated, with "week" for pw/per week, "month" for pcm/per month, "unknown" if no period is stated.
- letType: short_let, flexible, periodic (ordinary long let), corporate, licence, or unknown.
- propertyType: flat (also apartment, penthouse, studio), maisonette, detached, semi_detached, terraced (also end of terrace, mews), house (other houses), or unknown.
- agent: the letting agent or landlord named for this listing ("Marketed by …"), else null.
- priceReduced: true if the email says the rent was reduced, else null.
- availableFrom: ISO date (YYYY-MM-DD); "available now" means today's date, given below.
- highlight: one short German phrase for the most notable feature (e.g. "Garten nach Süden"), or null.
- photos: image URLs that belong to the listing (no logos or icons).`;

/**
 * generateContent body. thinkingLevel low/medium/high works on Gemini 3.x and 4 models;
 * maxOutputTokens includes the thinking tokens, so the limits leave room for them.
 */
function geminiRequest({ system, user, schema, thinkingLevel, maxOutputTokens }) {
  return {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: "user", parts: [{ text: user }] }],
    generationConfig: {
      responseMimeType: "application/json",
      responseJsonSchema: schema,
      maxOutputTokens,
      thinkingConfig: { thinkingLevel },
    },
  };
}

function extractionRequest(mail, today = new Date()) {
  const text = mail.text.length > MAX_MAIL_CHARS ? mail.text.slice(0, MAX_MAIL_CHARS) : mail.text;
  return geminiRequest({
    system: EXTRACTION_SYSTEM,
    user: `Today: ${today.toISOString().slice(0, 10)}\nFrom: ${mail.from}\nSubject: ${mail.subject}\n\n${text}`,
    schema: EXTRACTION_SCHEMA,
    thinkingLevel: "low",
    maxOutputTokens: 16384,
  });
}

/** Text of a generateContent answer (thought parts skipped). Throws with a readable reason when there is none. */
function readText(body) {
  if (!body || body.error) {
    throw new Error(`Gemini API error: ${body?.error?.message ?? JSON.stringify(body).slice(0, 300)}`);
  }
  if (body.promptFeedback?.blockReason) throw new Error(`Gemini blocked the request (${body.promptFeedback.blockReason})`);
  const candidate = body.candidates?.[0];
  if (!candidate) throw new Error("Gemini answer has no candidate");
  if (candidate.finishReason === "MAX_TOKENS") throw new Error("Gemini answer was cut off at maxOutputTokens");
  if (candidate.finishReason && candidate.finishReason !== "STOP") throw new Error(`Gemini stopped early (${candidate.finishReason})`);
  const text = (candidate.content?.parts ?? []).filter((p) => !p.thought && typeof p.text === "string").map((p) => p.text).join("");
  if (!text) throw new Error("Gemini answer has no text");
  return text;
}

/** Parses a structured-output answer. */
function readJson(body) {
  return JSON.parse(readText(body));
}

/** Extraction answer → listings in the parser's shape (pricePeriod "unknown" back to null). */
function readExtraction(body) {
  return readJson(body).listings.map((l) => ({ ...l, pricePeriod: l.pricePeriod === "unknown" ? null : l.pricePeriod }));
}

const FAMILY = `Die Familie (2 Erwachsene, 2 Kinder) sucht für 6 Monate ab Januar 2028 ein möbliertes Haus oder eine Wohnung in London.
Die Kinder gehen auf die Deutsche Schule London (DSL), Douglas House, Petersham Road, Richmond TW10 7AH.
Gebiete nach Priorität: Petersham und Ham (zu Fuß zur Schule), Richmond (Bus 65/371), North Kingston und East Sheen, Wimbledon/Southfields nur zum Vergleich.
Seit Mai 2026 gibt es keine befristeten Mietverträge mehr: Short Lets, Licences, Flexible und Corporate Lets passen zur Laufzeit; reguläre unbefristete Miete ist günstiger, aber Vermieter wollen meist Langzeitmieter.`;

const PROPERTY_LABEL = {
  flat: "Wohnung", maisonette: "Maisonette", detached: "Freistehendes Haus", semi_detached: "Doppelhaushälfte",
  terraced: "Reihenhaus", house: "Haus",
};

const SCALE = "1 = Nein, 2 = Eher nicht, 3 = Vielleicht, 4 = Interessant, 5 = Unbedingt";

/** Short listing description for prompts (also used for the few-shot examples). */
function describe(l) {
  const c = l.commute ?? {};
  const school = [
    c.walkMin != null && `${c.walkMin} Min. zu Fuß`,
    c.transitMin != null && `${c.transitMin} Min. mit ${c.transitSummary ?? "ÖPNV"}`,
  ].filter(Boolean).join(", ") || "unbekannt";
  return [
    `Adresse: ${l.address}${l.area ? `, ${l.area}` : ""} (${l.postcode || "Postcode unbekannt"})`,
    PROPERTY_LABEL[l.propertyType] ? `Objekt: ${PROPERTY_LABEL[l.propertyType]}` : null,
    `Miete: ${l.priceMonthly != null ? `£${l.priceMonthly} pcm` : "unbekannt"}${l.billsIncluded ? ", Nebenkosten inklusive" : ""}${l.priceReduced ? " (gesenkt)" : ""}`,
    `Mietform: ${l.letType}${l.minTermMonths || l.maxTermMonths ? ` (${l.minTermMonths ?? "?"}–${l.maxTermMonths ?? "?"} Monate)` : ""}`,
    `Verfügbar ab: ${l.availableFrom ?? "unbekannt"}`,
    `Zimmer: ${l.beds ?? "?"} Schlafzimmer, ${l.baths ?? "?"} Bäder; Einrichtung: ${l.furnished}`,
    `Garten: ${l.garden == null ? "unbekannt" : l.garden ? "ja" : "nein"}; Parkplatz: ${l.parking == null ? "unbekannt" : l.parking ? "ja" : "nein"}`,
    `Schulweg zur DSL: ${school}`,
    l.sizeSqm ? `Größe: ${l.sizeSqm} m²` : null,
    l.keyFeatures?.length ? `Merkmale laut Inserat: ${l.keyFeatures.slice(0, 8).join("; ")}` : null,
    l.description ? `Beschreibung (Auszug): ${l.description.replace(/\s+/g, " ").slice(0, 600)}` : null,
    l.letAgreed ? "Laut Portal bereits vermietet." : null,
    l.highlight ? `Besonderheit: ${l.highlight}` : null,
    l.flags?.length ? `Hinweise: ${l.flags.join(", ")}` : null,
  ].filter(Boolean).join("\n");
}

/**
 * What the model knows when judging (spec §6.3): family, confirmed guard rails, profile rules and
 * few-shot examples with the family's ratings. Shared by the prediction and the weekly backtest.
 */
function judgeSystem(context) {
  const profile = context.profile;
  const criteria = context.criteria ?? {};
  const hard = { ...criteria, ...(profile?.hardFilters ?? {}) };
  const guard = [
    hard.maxPriceMonthly != null && `Budget bis £${hard.maxPriceMonthly} pcm`,
    hard.minBeds != null && `mindestens ${hard.minBeds} Schlafzimmer`,
    hard.maxCommuteMin != null && `Schulweg höchstens ${hard.maxCommuteMin} Min.`,
  ].filter(Boolean);
  const examples = (context.examples ?? [])
    .map((e, i) => `Beispiel ${i + 1} – Bewertung ${e.score}${e.tags?.length ? ` (Gründe: ${e.tags.join(", ")})` : ""}${e.notes?.length ? `; Notizen: ${e.notes.join(" / ")}` : ""}\n${describe(e.listing)}`)
    .join("\n\n");

  return [
    `Du schätzt ein, wie interessant ein Mietinserat für eine Familie ist. Skala: ${SCALE}.`,
    FAMILY,
    guard.length ? `Bestätigte Leitplanken: ${guard.join("; ")}.` : "Leitplanken (Budget, Zimmer, Schulweg) sind noch nicht festgelegt.",
    profile?.rules?.length
      ? `Gelernte Vorlieben (Profil v${profile.version}):\n- ${profile.rules.join("\n- ")}`
